tool_calls:
mkdir -p /reports
awk '
$1 == "PASS" { passed++; total++ }
$1 == "FAIL" { failed++; total++; name = $0; sub(/^FAIL[[:space:]]+/, "", name); failures = failures "- " name "\n" }
END {
  print "# Test Summary"
  printf "Total: %d | Passed: %d | Failed: %d\n", total, passed, failed
  print ""
  print "## Failures"
  printf "%s", failures
}' /data/test-results.txt > /reports/test-summary.md
cat /reports/test-summary.md

